input.sparql:
SELECT ?zn ?point WHERE {
  ?zn a brick:Zone .
  ?zn rdfs:label ?l .
  FILTER(?l IN ("Perimeter_mid_ZN_1","Perimeter_mid_ZN_2"))
  ?point brick:isPartOf ?zn .
} LIMIT 40

SELECT ?zn ?l WHERE {
  ?zn a brick:Zone .
  OPTIONAL { ?zn rdfs:label ?l }
} LIMIT 40

SELECT ?zn ?l WHERE {
  ?zn a brick:Location .
  OPTIONAL { ?zn rdfs:label ?l }
} LIMIT 40

